<script setup lang="ts">
import {localize} from './localization';

import {computed,inject,ref,watch} from 'vue';
import {useSession} from './store';
import type {Material} from '../../../packages/schema/index';
import {materialInUse} from '../../../packages/manufacturing/dependencies';
const advanced=inject('advancedMode',ref(false));
const props=defineProps<{language:'zh'|'en';selectedId:string;targetId?:string}>(),store=useSession(),zh=computed(()=>props.language==='zh'),id=ref(''),rotations=ref('0'),defaultWidth=ref(10);
const fresh=():Material=>({id:crypto.randomUUID(),version:1,name:zh.value?'新材料':localize('New material'),category:'fur',thicknessMm:2,furLengthMm:20,compensationMm:0,defaultAllowanceMm:10,furRequired:true,grainRequired:false,rotationsRad:[0],seamToleranceMm:2,stretchWarpRatio:0,stretchWeftRatio:0,measurementSource:'estimated',sourceNote:''}),form=ref<Material>(fresh());
const selected=computed(()=>store.data.project?.pieces.find(p=>p.id===props.selectedId)),existing=computed(()=>store.data.project?.materials?.find(m=>m.id===id.value));
watch(()=>existing.value?existing.value.id+':'+existing.value.version:'',()=>{const m=existing.value;form.value=m?JSON.parse(JSON.stringify(m)):fresh();rotations.value=form.value.rotationsRad.map(v=>v*180/Math.PI).join(',');},{immediate:true});watch(()=>store.data.project?.defaultAllowanceMm,v=>defaultWidth.value=v??10,{immediate:true});
watch(()=>props.targetId,target=>{if(target&&store.data.project?.materials?.some(m=>m.id===target))id.value=target;});
function create(){id.value='';form.value=fresh();rotations.value='0';}
async function save(){const p=store.data.project;if(!p)return;const material={...JSON.parse(JSON.stringify(form.value)),id:existing.value?.id??form.value.id,version:existing.value?existing.value.version+1:1,rotationsRad:rotations.value.split(',').map(v=>Number(v.trim())*Math.PI/180)};if(await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'material.put',material})))id.value=material.id;}
async function remove(){const p=store.data.project;if(p&&existing.value&&await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'material.delete',materialId:id.value})))create();}
async function assign(){const p=store.data.project,piece=selected.value,m=existing.value;if(p&&piece&&m)await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'piece.put',piece:{...JSON.parse(JSON.stringify(piece)),materialId:m.id,material:m.name,allowanceSource:'material'}}));}
async function detach(){const p=store.data.project,piece=selected.value;if(p&&piece)await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'piece.put',piece:{...JSON.parse(JSON.stringify(piece)),materialId:undefined,allowanceSource:'piece'}}));}
async function setDefault(){const p=store.data.project;if(p)await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'project.allowance',widthMm:defaultWidth.value}));}
const labels:Record<string,string>={thicknessMm:'实物厚度 mm',furLengthMm:'视觉毛长 mm',compensationMm:'有效制造补偿 mm',defaultAllowanceMm:'默认缝份 mm',seamToleranceMm:'缝长公差上限 mm',stretchWarpRatio:'经向伸长比（0.1 = 10%）',stretchWeftRatio:'纬向伸长比（0.1 = 10%）'};
</script>
<template><section class="materials-panel"><p v-if="advanced">{{zh?'材料保存于项目快照；版本更新会使旧排料失效。毛长只用于记录，不自动加到裁片；有效补偿可在模板表单中显式采用。弹性记录不会自动缩放纸样，也不代表试穿模拟。':localize('Materials are versioned project snapshots; updates invalidate nesting. Fur length is visual metadata. Compensation is explicitly applied in the template form. Stretch records do not resize patterns or simulate fit.')}}</p><div class="material-controls"><label>{{zh?'项目默认缝份 mm':localize('Project default allowance mm')}}<input v-model.number="defaultWidth" type="number" min="0" max="1000"></label><button :disabled="store.busy" @click="setDefault">{{zh?'保存项目默认缝份':localize('Save project allowance')}}</button><select v-model="id"><option value="">{{zh?'新材料':localize('New material')}}</option><option v-for="m in store.data.project?.materials??[]" :key="m.id" :value="m.id">{{m.name}} v{{m.version}}</option></select><button @click="create">{{zh?'新建材料':localize('New material')}}</button></div><div class="material-form"><label>{{zh?'名称':localize('Name')}}<input v-model="form.name" maxlength="120"></label><label>{{zh?'类别':localize('Category')}}<select v-model="form.category"><option value="fur">{{zh?'毛皮':localize('Fur')}}</option><option value="foam">{{zh?'泡棉':localize('Foam')}}</option><option value="lining">{{zh?'内衬':localize('Lining')}}</option><option value="other">{{zh?'其他':localize('Other')}}</option></select></label><label v-for="key in (advanced?Object.keys(labels):['thicknessMm','furLengthMm','defaultAllowanceMm']) as (keyof Material)[]" :key="key">{{zh?labels[key]:localize(key)}}<input v-model.number="form[key]" type="number" min="0" :step="key.includes('Ratio')?.01:.5"></label><label v-if="advanced">{{zh?'允许相对转角 °（逗号分隔）':localize('Allowed relative rotations ° (comma separated)')}}<input v-model="rotations"></label><label><input v-model="form.furRequired" type="checkbox">{{zh?'必须毛向':localize('Fur direction required')}}</label><label><input v-model="form.grainRequired" type="checkbox">{{zh?'必须布向':localize('Grain required')}}</label><label v-if="advanced">{{zh?'参数来源':localize('Measurement source')}}<select v-model="form.measurementSource"><option value="estimated">{{zh?'估计，制造前需确认':localize('Estimated; review before manufacturing')}}</option><option value="measured">{{zh?'用户实测记录':localize('User measurement')}}</option></select></label><label v-if="advanced">{{zh?'测量条件 / 来源备注':localize('Conditions / source note')}}<input v-model="form.sourceNote" maxlength="300"></label></div><div class="material-controls"><button :disabled="store.busy" @click="save">{{zh?'保存材料版本':localize('Save material version')}}</button><button :disabled="store.busy||!existing||!selected" @click="assign">{{zh?'关联所选纸样并使用材料默认':localize('Assign selected piece and use material default')}}</button><button :disabled="store.busy||!selected?.materialId" @click="detach">{{zh?'解除所选纸样材料关联':localize('Detach selected piece material')}}</button><button :disabled="store.busy||!existing||!!store.data.project&&materialInUse(store.data.project,id)" @click="remove">{{zh?'删除未使用材料':localize('Delete unused material')}}</button></div></section></template>
<style scoped>section{padding:12px;font-size:12px}p{line-height:1.5}.material-controls,.material-form{display:flex;gap:10px;flex-wrap:wrap;margin:12px 0}.material-form label{width:185px}.material-form input:not([type=checkbox]){width:100%}.material-controls label{max-width:185px}</style>
